<script setup lang="ts">
import InfiniteList from './components/InfiniteList.vue'
import {ref,reactive,onMounted,onBeforeUnmount,computed,defineAsyncComponent,nextTick,watch} from 'vue'
import {appendUnique,api,body,loadSession,session,list,date,type Row} from './api'
import {clearRecovery} from './storage'
import {initLiquidGlass} from './liquidGlass'
import {registerMobileOverlay} from './mobileOverlays'
import Icon from './components/Icon.vue'
import PasswordForm from './components/PasswordForm.vue'
import AccountSecurity from './components/AccountSecurity.vue'
import LoginPolicySettings from './components/LoginPolicySettings.vue'
import IdentityClients from './components/IdentityClients.vue'
import GitHubSettings from './components/GitHubSettings.vue'
import SelectField from './components/SelectField.vue'
import StudioSidebar from './components/StudioSidebar.vue'
import PhraseManager from './components/PhraseManager.vue'
import FriendManager from './components/FriendManager.vue'
import PostManager from './components/PostManager.vue'
import SeriesManager from './components/SeriesManager.vue'
import TagManager from './components/TagManager.vue'
import MomentManager from './components/MomentManager.vue'
import HomepageManager from './components/HomepageManager.vue'
import ProductManager from './components/ProductManager.vue'
import AuthorProfileSettings from './components/AuthorProfileSettings.vue'
import './profileCentre.css'
import {confirmAction} from './confirm'
import {toast} from './toast'
import {navigation,currentNavigation,settingsSection as resolveSettingsSection} from './navigation'
const MarkdownEditor=defineAsyncComponent(()=>import('./components/MarkdownEditor.vue'))
const path=location.pathname.replace(/\/$/,'')||'/me',editing=/^\/studio\/posts\/(new|[^/]+)$/.test(path),postId=path.split('/')[3]==='new'?undefined:path.split('/')[3]
const allowAnalytics=ref(localStorage.getItem('painter-analytics')!=='off')
function privacyChange(){localStorage.setItem('painter-analytics',allowAnalytics.value?'on':'off');toast.success(allowAnalytics.value?'已允许本浏览器的访问统计。':'已关闭本浏览器的访问统计。')}
const error=ref(''),errorCode=ref(''),dataLoaded=ref(false),loading=ref(true),busy=ref(false),rows=ref<Row[]>([]),cursor=ref<string|null>(null),hasMore=ref(false),profile=reactive<Row>({}),settings=reactive<Row>({}),site=reactive<Row>({}),report=ref<Row>({}),moderationReason=ref(''),range=reactive({from:new Date(Date.now()-6*86400000).toISOString().slice(0,10),to:new Date().toISOString().slice(0,10)})
const navigationGroups=computed(()=>navigation(session.user?.role||''))
const introRolesText=ref('')
const profileBaseline=ref(''),siteBaseline=ref(''),settingsBaseline=ref('')
const profileSnapshot=()=>JSON.stringify(['username','display_name','bio','email','phone','avatar_media_id'].map(key=>profile[key]||(key==='avatar_media_id'?null:'')))
const siteSnapshot=()=>JSON.stringify([site,introRolesText.value])
const settingsSnapshot=()=>JSON.stringify(['comments_enabled','collections_enabled','follows_enabled','analytics_enabled','mail_enabled','rss_enabled','floating_controls','smtp_host','smtp_port','smtp_username','smtp_password','mail_from'].map(key=>key==='smtp_password'?(settings[key]||''):(settings[key]??null)))
const profileDirty=computed(()=>dataLoaded.value&&path==='/me'&&profileSnapshot()!==profileBaseline.value)
const siteDirty=computed(()=>dataLoaded.value&&path==='/studio/settings'&&siteSnapshot()!==siteBaseline.value)
const settingsDirty=computed(()=>dataLoaded.value&&path==='/studio/settings'&&settingsSnapshot()!==settingsBaseline.value)
function protectUnsaved(event:BeforeUnloadEvent){if(profileDirty.value||siteDirty.value||settingsDirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',protectUnsaved))
onBeforeUnmount(()=>window.removeEventListener('beforeunload',protectUnsaved))
const mobileQuery=matchMedia('(max-width:960px)'),phoneQuery=matchMedia('(max-width:720px)'),mobile=ref(mobileQuery.matches),phone=ref(phoneQuery.matches),drawer=ref<HTMLDialogElement>(),settingsSection=ref(resolveSettingsSection(location.hash))
function resolveProfileSection(){return location.hash==='#account-security-title'?'security':['profile','appearance'].includes(location.hash.slice(1))?location.hash.slice(1):'overview'}
const phoneProfileSection=ref(resolveProfileSection()),profileSectionsSeen=reactive(new Set([resolveProfileSection()])),phoneSecuritySection=ref('access'),keyboardOpen=ref(false),drawerOpen=ref(false)
const phoneProfileTabs=[{id:'overview',label:'我的'},{id:'profile',label:'资料'},{id:'appearance',label:'公开主页'},{id:'security',label:'安全'}]
const settingsSecuritySeen=ref(path==='/studio/settings'&&settingsSection.value==='security'),phoneSecuritySeen=reactive(new Set(['access']))
watch(settingsSection,id=>{if(id==='security')settingsSecuritySeen.value=true})
watch(phoneSecuritySection,id=>phoneSecuritySeen.add(id))
watch([phone,settingsSecuritySeen],()=>{if(settingsSecuritySeen.value&&!phone.value){phoneSecuritySeen.add('github');phoneSecuritySeen.add('clients')}},{immediate:true})
const phoneSecurityTabs=[{id:'access',label:'访问控制'},{id:'github',label:'GitHub'},{id:'clients',label:'应用接入'}]
const canCreate=computed(()=>['owner','author'].includes(session.user?.role||''))
const contentDestination=computed(()=>canCreate.value?'/studio/posts':'/me/bookmarks')
const phoneTaskTitle=computed(()=>editing?(postId?'编辑文章':'写新文章'):path==='/me'?({overview:'个人中心',profile:'个人资料',appearance:'公开主页',security:'账号安全'} as Record<string,string>)[phoneProfileSection.value]:title.value)
const phoneBack=computed(()=>editing?'/studio/posts':path.startsWith('/me/')?'/me':'/')
const phoneBackLabel=computed(()=>editing?'返回文章列表':path.startsWith('/me/')?'返回个人空间':'返回网站')
let viewportBaseline=innerHeight,glassGeneration=0,glassCleanup=()=>{}
const editableFocus=()=>document.activeElement instanceof HTMLElement&&document.activeElement.matches('input:not([type=checkbox]):not([type=radio]),textarea,[contenteditable=true]')
function syncKeyboard(){const height=window.visualViewport?.height||innerHeight;if(!editableFocus())viewportBaseline=innerHeight;keyboardOpen.value=phone.value&&editableFocus()&&Math.max(viewportBaseline,innerHeight)-height>150}
function focusChanged(){requestAnimationFrame(syncKeyboard)}
function refreshWorkbenchGlass(){const generation=++glassGeneration;glassCleanup();glassCleanup=()=>{};void nextTick(()=>{if(generation!==glassGeneration)return;glassCleanup=initLiquidGlass(document.querySelector('.workbench')||document)})}
function taskTabsKey(e:KeyboardEvent){const buttons=Array.from((e.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('[role=tab]')),index=buttons.indexOf(e.target as HTMLButtonElement);if(index<0)return;let next=index;if(e.key==='ArrowRight')next=(index+1)%buttons.length;else if(e.key==='ArrowLeft')next=(index+buttons.length-1)%buttons.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=buttons.length-1;else return;e.preventDefault();buttons[next].click();buttons[next].focus()}
function profileSectionChange(id:string){phoneProfileSection.value=id;profileSectionsSeen.add(id);history.replaceState(history.state,'',id==='overview'?location.pathname+location.search:id==='security'?'#account-security-title':'#'+id)}
function closeDrawer(){drawer.value?.close();drawerOpen.value=false;document.body.classList.remove('studio-navigation-open')}
function drawerClosed(){drawerOpen.value=false;document.body.classList.remove('studio-navigation-open')}

const drawerSidebar=ref<InstanceType<typeof StudioSidebar>>()
watch(drawer,(dialog,_previous,onCleanup)=>{if(dialog)onCleanup(registerMobileOverlay(dialog,openDrawer))},{flush:'post'})
function openDrawer(){if(!drawer.value||drawer.value.open)return;drawer.value.showModal();drawerOpen.value=true;document.body.classList.add('studio-navigation-open');void nextTick(()=>drawerSidebar.value?.revealCurrent())}
function resizeLayout(){mobile.value=mobileQuery.matches;phone.value=phoneQuery.matches;viewportBaseline=innerHeight;closeDrawer();syncKeyboard();refreshWorkbenchGlass()}
mobileQuery.addEventListener('change',resizeLayout)
phoneQuery.addEventListener('change',resizeLayout)
window.visualViewport?.addEventListener('resize',syncKeyboard)
window.addEventListener('resize',syncKeyboard)
document.addEventListener('focusin',focusChanged)
document.addEventListener('focusout',focusChanged)
function syncLocation(){settingsSection.value=resolveSettingsSection(location.hash);if(path==='/me'){phoneProfileSection.value=resolveProfileSection();profileSectionsSeen.add(phoneProfileSection.value)}}
let sessionRedirecting=false
function sessionExpired(){if(sessionRedirecting)return;sessionRedirecting=true;location.assign('/login?return_to='+encodeURIComponent(location.pathname+location.search+location.hash))}
window.addEventListener('painter:session-expired',sessionExpired)
window.addEventListener('hashchange',syncLocation);window.addEventListener('popstate',syncLocation)
onBeforeUnmount(()=>{window.removeEventListener('painter:session-expired',sessionExpired);mobileQuery.removeEventListener('change',resizeLayout);phoneQuery.removeEventListener('change',resizeLayout);window.visualViewport?.removeEventListener('resize',syncKeyboard);window.removeEventListener('resize',syncKeyboard);document.removeEventListener('focusin',focusChanged);document.removeEventListener('focusout',focusChanged);window.removeEventListener('hashchange',syncLocation);window.removeEventListener('popstate',syncLocation);document.body.classList.remove('studio-navigation-open');glassGeneration++;glassCleanup()})
watch(()=>session.authenticated,refreshWorkbenchGlass)
onMounted(refreshWorkbenchGlass)
const navigationPosition=computed(()=>currentNavigation(navigationGroups.value,path,'#'+settingsSection.value))
function changeSection(id:string){settingsSection.value=id;history.replaceState(null,'','#'+id)}
function settingsKey(e:KeyboardEvent){const buttons=Array.from((e.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('[role=tab]')),index=buttons.indexOf(e.target as HTMLButtonElement);let next=index;if(e.key==='ArrowRight')next=(index+1)%buttons.length;else if(e.key==='ArrowLeft')next=(index+buttons.length-1)%buttons.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=buttons.length-1;else return;e.preventDefault();buttons[next].click();buttons[next].focus()}
const title=computed(()=>({'/studio/home':'首页内容','/studio/products':'产品','/studio/series':'专栏管理','/studio/posts':session.user?.role==='owner'?'文章管理':'我的文章','/studio/moments':session.user?.role==='owner'?'动态管理':'我的动态','/me':'个人中心','/me/bookmarks':'收藏文章','/me/following':'关注与粉丝','/me/followers':'关注与粉丝','/me/history':'阅读足迹','/me/sessions':'登录会话','/me/media':'我的媒体','/studio/settings':'站点设置','/studio/friends':'友链','/studio/phrases':'片语','/studio/taxonomy':'标签管理','/studio/members':'成员权限','/studio/comments':'评论管理','/studio/analytics':session.user?.role==='owner'?'站点访问分析':'我的文章分析','/studio/operations':'存储与任务'}[path]||'个人空间'))
const description=computed(()=>({'/studio/home':'编排首页介绍、文章与自己的游戏、唱片和照片。','/studio/products':'管理真实产品的介绍、图片与公开入口。','/studio/series':'将已有文章编排成有顺序的连载章节。','/studio/posts':'草稿、线上文章和回收站，都在这里。','/studio/moments':'记录此刻的想法，保存草稿后再发布。','/me':'管理自己的阅读、公开资料与账号安全。收藏、足迹和联系方式只对本人可见。','/me/bookmarks':'把值得重读的文章留在身边。','/me/history':'从上一次阅读继续。','/studio/analytics':session.user?.role==='owner'?'查看全站业务与访问情况，业务事实与访问估算分别呈现。':'查看自己文章的访问情况，当前数据范围仅包含你的文章。','/studio/settings':'网站信息、功能与登录，各有清晰的位置。','/studio/friends':'为值得相遇的网站，留一个位置。','/studio/phrases':'留下一句话，或一个值得停留的词。'}[path]||'管理你的内容与账户。'))
function show(e:unknown){if((e as {status?:number})?.status===401){sessionExpired();return}error.value=(e as Error).message||'操作失败，请重试';errorCode.value=(e as {code?:string}).code||''}
async function task(fn:()=>Promise<void>){busy.value=true;error.value='';errorCode.value='';try{await fn()}catch(e){if((e as {status?:number})?.status===401||(e as {code?:string})?.code==='VERSION_CONFLICT'||(e as {code?:string})?.code==='VALIDATION_FAILED')show(e);else toast.error((e as Error).message||'操作失败，请重试')}finally{busy.value=false}}
function endpoint(){if(path==='/studio/members')return '/admin/users';if(path==='/studio/comments')return '/admin/comments';return path.startsWith('/me/')?path:''}
let listReadVersion=0
onBeforeUnmount(()=>{listReadVersion++})
async function load(append=false){if(append&&(loading.value||busy.value||!cursor.value))return;const generation=++listReadVersion;loading.value=true;error.value='';errorCode.value='';try{
 const ep=endpoint();if(ep){const data=await api(ep+(append&&cursor.value?(ep.includes('?')?'&':'?')+'cursor='+encodeURIComponent(cursor.value):''));if(generation!==listReadVersion)return;rows.value=append?appendUnique(rows.value,list(data)):list(data);cursor.value=data.next_cursor;hasMore.value=data.has_more}
 else if(path==='/me'){Object.assign(profile,await api('/me'));profileBaseline.value=profileSnapshot()}
 else if(path==='/studio/settings'){const [a,b]=await Promise.all([api('/admin/site-profile'),api('/admin/settings')]);Object.assign(site,a);site.social_links=a.social_links||[];site.intro_roles=a.intro_roles||[];introRolesText.value=site.intro_roles.join('、');Object.assign(settings,b);settings.floating_controls=b.floating_controls||{home:['theme','top','account'],article:['theme','top','bottom','like','account'],other:['theme','top','account']}}
 else if(path==='/studio/analytics'){const ep=session.user?.role==='owner'?'/admin/analytics':'/me/analytics';report.value=await api(ep+`?day_from=${range.from}&day_to=${range.to}`);rows.value=list(report.value)}
 else if(path==='/studio/operations'){const [storage,jobs]=await Promise.all([api('/admin/storage'),api('/admin/jobs')]);report.value={storage,jobs}}
 if(path==='/studio/settings'){siteBaseline.value=siteSnapshot();settingsBaseline.value=settingsSnapshot()}
 dataLoaded.value=true
 }catch(e){if(generation===listReadVersion)show(e)}finally{if(generation===listReadVersion)loading.value=false}}
async function logout(){await task(async()=>{if(!await confirmAction('退出登录？','请先导出未同步的内容。退出会清理本账号的浏览器恢复点。','退出登录'))return;const userID=session.user.id;await api('/session',{method:'DELETE'});await clearRecovery(userID).catch(()=>{});location.href='/'})}
async function reloadProfile(){if(busy.value||!await confirmAction('重新读取个人资料？','这会放弃当前未保存的资料修改，并读取服务器最新版本。','重新读取'))return;busy.value=true;try{await load()}finally{busy.value=false}}
async function saveProfile(){await task(async()=>{const fields=['username','display_name','bio','email','phone','avatar_media_id'];const data=Object.fromEntries(fields.map(k=>[k,profile[k]||((k==='avatar_media_id')?null:'')]));Object.assign(profile,await api('/me',{method:'PATCH',version:profile.version,body:body(data)}));if(session.user)Object.assign(session.user,{username:profile.username,display_name:profile.display_name,avatar_url:profile.avatar_url,bio:profile.bio,version:profile.version});profileBaseline.value=profileSnapshot();toast.success('个人资料已更新。')})}
async function avatarUpload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await task(async()=>{const data=new FormData();data.append('file',file);const res=await api('/media',{method:'POST',body:data,idempotent:true});profile.avatar_media_id=res.media_id;toast.success('头像已上传，保存资料后生效。')})}
async function siteAvatarUpload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await task(async()=>{const data=new FormData();data.append('file',file);const res=await api('/media',{method:'POST',body:data,idempotent:true});site.avatar_media_id=res.media_id;toast.success('站点头像已上传，保存网站信息后生效。')})}
async function saveSite(){await task(async()=>{const data:Row={...site,social_links:site.social_links||[],intro_roles:introRolesText.value.split(/[、,，\n]/).map(s=>s.trim()).filter(Boolean)};Object.assign(site,await api('/admin/site-profile',{method:'PUT',version:site.version,body:body(data)}));siteBaseline.value=siteSnapshot();toast.success('网站信息已保存。')})}
async function saveSettings(){await task(async()=>{const data={...settings};delete data.smtp_password_configured;if(!data.smtp_password)delete data.smtp_password;Object.assign(settings,await api('/admin/settings',{method:'PUT',version:settings.version,body:body(data)}));settings.smtp_password='';settingsBaseline.value=settingsSnapshot();toast.success('功能与通知设置已保存。')})}
async function saveMember(row:Row){await task(async()=>{await api(`/admin/users/${row.id}`,{method:'PATCH',idempotent:true,body:body({role:row.role,disabled:!!row.disabled})});toast.success('成员权限已更新。');await load()})}
async function moderate(row:Row,state:string){if(busy.value||!['visible','hidden'].includes(row.state))return;await task(async()=>{await api(`/admin/comments/${row.id}/visibility`,{method:'PUT',idempotent:true,body:body({state,reason:moderationReason.value})});toast.success('评论状态已更新。');await load()})}
async function removeBookmark(row:Row){await task(async()=>{await api(`/posts/${row.post_id||row.id}/bookmark`,{method:'DELETE'});toast.success('已取消收藏。');await load()})}
async function follow(row:Row){await task(async()=>{await api(`/users/${row.id}/follow`,{method:row.followed===false?'PUT':'DELETE'});toast.success(row.followed===false?'已关注。':'已取消关注。');await load()})}
async function revoke(row:Row){await task(async()=>{await api(`/me/sessions/${row.management_id||row.id}`,{method:'DELETE'});if(row.current){await clearRecovery(session.user.id).catch(()=>{});location.href='/login'}else{toast.success('登录会话已退出。');await load()}})}
function canDeleteMedia(row:Row){return !row.in_use&&['ready','failed'].includes(row.state)}
function mediaState(row:Row){return ({ready:'可用',staging:'上传中',failed:'上传失败',deleting:'删除中',deleted:'已删除'} as Row)[row.state]||row.state}
async function deleteMedia(row:Row){if(busy.value||!canDeleteMedia(row))return;await task(async()=>{await api(`/media/${row.id||row.media_id}`,{method:'DELETE'});await load();toast.success('未引用的媒体已删除。')})}
async function clearHistory(){await task(async()=>{if(await confirmAction('清空阅读足迹？','这会移除本账号全部阅读足迹，文章和收藏不受影响。','清空足迹')){await api('/me/history',{method:'DELETE'});toast.success('阅读足迹已清空。');await load()}})}
const fields:Record<string,string>={database_bytes:'数据库占用',media_bytes:'媒体占用',ready_media_bytes:'可用媒体大小',ready_media_count:'可用媒体数量',media_disk_bytes:'媒体磁盘占用',media_file_count:'磁盘文件数',backup:'备份状态',items:'任务状态',dead_tasks:'失败任务',analytics:'聚合状态',lag_ms:'聚合延迟（毫秒）',max_processed_seq_diagnostic:'处理序号（仅诊断）',state:'状态',count:'数量',oldest_at:'最早创建时间',max_attempts:'最高尝试次数',topic:'任务类型',attempts:'尝试次数',error:'错误',created_at:'创建时间',id:'任务编号',ready_count:'可用媒体',staging_count:'上传中',unreferenced_count:'未引用媒体',pending_count:'待处理事件',outbox_pending:'待执行任务',outbox_dead:'失败任务',oldest_pending_at:'最早待处理时间',worker_lag_ms:'聚合延迟（毫秒）',data_as_of:'统计截至',total_bytes:'总占用',object_count:'媒体对象数',database_size:'数据库占用',media_count:'媒体对象数'}
function metricLabel(k:string){return fields[k]||({'page_views':'浏览次数','post_reads':'有效阅读','unique_visitors':'每日估算访客','search_submits':'搜索次数','search_result_opens':'搜索结果打开','editor_opens':'编辑器打开','editor_errors':'编辑错误','identified_page_views':'有标识浏览','posts_published':'发布次数','comments_created':'新增评论'} as Row)[k]||k}
const totals=computed(()=>['page_views','post_reads','search_submits','editor_errors'].map(k=>({key:k,value:rows.value.filter(r=>session.user?.role==='owner'?(!r.resource_key||r.resource_key==='site'):String(r.resource_key||'').startsWith('post:')).reduce((n,r)=>n+Number(r[k]||0),0)})))
onMounted(async()=>{try{await loadSession();if(!session.authenticated){sessionExpired();return}if(!editing)await load()}catch(e){show(e);loading.value=false}})
</script>
<template>
 <div class="workbench" :class="{'is-phone':phone,'is-keyboard-open':keyboardOpen,'is-editing':editing}"><aside v-if="!mobile" class="work-nav"><StudioSidebar :groups="navigationGroups" :path="path" :hash="'#'+settingsSection" :user="session.user" :busy="busy" @logout="logout"/></aside><template v-else><header v-if="phone" class="studio-phone-header" data-search-glass><a :href="phoneBack" class="phone-back" :aria-label="phoneBackLabel"><Icon name="arrow" :size="20"/></a><div><span>{{navigationPosition?.group.label||'Painter'}}</span><strong>{{phoneTaskTitle}}</strong></div><button type="button" aria-label="打开全部工作台功能" aria-haspopup="dialog" :aria-expanded="drawerOpen" @click="openDrawer"><Icon name="menu" :size="21"/></button></header><div v-else class="studio-mobile-bar"><a class="studio-mobile-brand" href="/"><img :src="'/assets/images/painter-logo.png'" width="30" height="30" alt="">Painter</a><button type="button" @click="openDrawer" aria-label="打开工作台导航"><Icon name="menu" :size="20"/>菜单</button></div><dialog ref="drawer" class="studio-drawer" :class="{'studio-navigation-sheet':phone}" aria-label="全部工作台功能" @close="drawerClosed" @click="($event.target===$event.currentTarget)&&closeDrawer()"><div v-if="phone" class="studio-sheet-heading"><h2>全部功能</h2><button type="button" class="quiet" aria-label="关闭全部功能" @click="closeDrawer"><Icon name="close" :size="21"/></button></div><button v-else type="button" class="drawer-close quiet" aria-label="关闭工作台导航" @click="closeDrawer"><Icon name="close" :size="20"/></button><StudioSidebar ref="drawerSidebar" :presentation="phone?'sheet':'rail'" :groups="navigationGroups" :path="path" :hash="'#'+settingsSection" :user="session.user" :busy="busy" @navigate="!phone&&closeDrawer()" @logout="closeDrawer();logout()"/></dialog></template><main id="main" class="work-main"><nav v-if="session.authenticated&&navigationPosition" class="work-breadcrumb" aria-label="当前位置"><span>{{navigationPosition.group.label}}</span><Icon name="chevron" :size="13"/><a v-if="editing" :href="navigationPosition.item.url">{{navigationPosition.item.label}}</a><span v-else aria-current="page">{{navigationPosition.item.label}}</span><template v-if="editing"><Icon name="chevron" :size="13"/><span aria-current="page">{{postId?'编辑文章':'写新文章'}}</span></template></nav>

 <div v-if="session.loading"><div class="loading-line"></div><div class="loading-line"></div></div>
 <MarkdownEditor v-else-if="editing&&session.authenticated" :post-id="postId"/>
 <template v-else-if="session.authenticated"><div class="work-heading"><div><h1>{{phone?phoneTaskTitle:title}}</h1><p>{{description}}</p></div><a v-if="path==='/studio/posts'" href="/studio/posts/new" class="button primary">写新文章</a></div>
 <div v-if="error" class="notice error" role="alert">{{error}} <button v-if="!dataLoaded" class="quiet" @click="load()">重新加载</button><button v-else-if="path==='/me'&&errorCode==='VERSION_CONFLICT'" class="quiet" :disabled="busy" @click="reloadProfile">重新读取资料</button><button v-else class="quiet" @click="error='';errorCode=''">关闭提示</button></div>
 <p v-if="loading&&dataLoaded" class="muted" role="status">正在更新…</p>
 <div v-if="loading&&!dataLoaded" class="panel" aria-label="正在加载"><div class="loading-line"></div><div class="loading-line"></div><div class="loading-line"></div></div>
 <template v-else-if="!error||dataLoaded">
 <ProductManager v-if="path==='/studio/products'&&session.user?.role==='owner'"/><FriendManager v-else-if="path==='/studio/friends'"/><PhraseManager v-else-if="path==='/studio/phrases'"/><PostManager v-else-if="path==='/studio/posts'" :owner="session.user?.role==='owner'"/><SeriesManager v-else-if="path==='/studio/series'"/>
 <template v-else-if="path==='/me'">
  <header class="profile-centre-identity"><img v-if="profile.avatar_media_id||profile.avatar_url" class="avatar" :src="profile.avatar_media_id?'/media/'+profile.avatar_media_id:profile.avatar_url" width="56" height="56" alt=""><span v-else class="avatar">{{(profile.display_name||'?').slice(0,1)}}</span><div><h2>{{profile.display_name}}</h2><p>@{{profile.username}} · {{({owner:'站长',author:'创作者',reader:'读者'} as Row)[session.user.role]||'读者'}}</p></div><a class="button quiet" :href="`/users/${session.user.id}`">公开主页<Icon name="arrow" :size="16"/></a></header>
  <div class="profile-task-tabs" role="tablist" aria-label="个人中心任务" @keydown="taskTabsKey"><button v-for="tab in phoneProfileTabs" :key="tab.id" :id="'profile-tab-'+tab.id" type="button" role="tab" :tabindex="phoneProfileSection===tab.id?0:-1" :aria-selected="phoneProfileSection===tab.id" :aria-controls="'phone-profile-'+tab.id" @click="profileSectionChange(tab.id)">{{tab.label}}</button></div>
  <section id="phone-profile-overview" v-show="phoneProfileSection==='overview'" role="tabpanel" aria-labelledby="profile-tab-overview" class="profile-overview">
   <div class="profile-reading-heading"><h2>继续阅读</h2><a href="/posts" class="text-link">发现文章<Icon name="arrow" :size="16"/></a></div>
   <nav class="profile-reading-links" aria-label="我的阅读"><a href="/me/bookmarks"><Icon name="bookmark" :size="21"/><span><strong>收藏文章</strong><small>留住值得重读的内容</small></span><Icon name="chevron" :size="17"/></a><a href="/me/following"><Icon name="users" :size="21"/><span><strong>我的关注</strong><small>找到你关注的人</small></span><Icon name="chevron" :size="17"/></a><a href="/me/history"><Icon name="history" :size="21"/><span><strong>阅读足迹</strong><small>从上一次阅读继续</small></span><Icon name="chevron" :size="17"/></a></nav>
   <section v-if="canCreate" class="profile-creation-entry"><div><h2>创作</h2><p>继续整理想法，或写下一篇文章</p></div><div class="actions"><a href="/studio/posts" class="button">管理文章</a><a href="/studio/posts/new" class="button primary">写新文章</a></div></section>
   <div class="profile-account-entry"><p>公开主页展示昵称、头像与简介。收藏、足迹和联系方式不会展示给其他人。</p><button type="button" class="quiet" @click="profileSectionChange('security')"><Icon name="shield" :size="18"/>账号安全<Icon name="arrow" :size="16"/></button><a href="/me/sessions" class="button quiet">登录设备</a></div>
  </section>
  <form id="phone-profile-profile" v-show="phoneProfileSection==='profile'" role="tabpanel" aria-labelledby="profile-tab-profile" class="panel profile-details-form" @submit.prevent="saveProfile"><div class="form-grid"><label>用户名<input v-model="profile.username" required maxlength="64" autocomplete="username"></label><label>公开昵称<input v-model="profile.display_name" required maxlength="100" autocomplete="nickname"></label><label class="full">公开简介<textarea v-model="profile.bio" maxlength="1000" rows="3"></textarea></label><label>邮箱（仅本人可见）<input v-model="profile.email" type="email" autocomplete="email"></label><label>电话（仅本人可见）<input v-model="profile.phone" type="tel" autocomplete="tel"></label><label>头像<img v-if="profile.avatar_media_id||profile.avatar_url" class="avatar" :src="profile.avatar_media_id?'/media/'+profile.avatar_media_id:profile.avatar_url" width="40" height="40" alt=""><span v-else class="avatar">{{(profile.display_name||'?').slice(0,1)}}</span><span class="button">选择头像<input class="sr-only" type="file" accept="image/jpeg,image/png,image/webp,image/gif" @change="avatarUpload"></span></label><div class="profile-privacy-setting"><label class="check"><input type="checkbox" v-model="allowAnalytics" @change="privacyChange">允许本浏览器的访问统计</label><p class="muted">联系方式仅作资料，不用于账号合并或找回密码。</p></div></div><div class="form-actions"><button class="primary" :disabled="busy">{{busy?'保存中…':'保存资料'}}</button><span v-if="profileDirty" class="muted" role="status">有未保存的修改</span></div></form>
  <div id="phone-profile-appearance" v-if="profileSectionsSeen.has('appearance')" v-show="phoneProfileSection==='appearance'" role="tabpanel" aria-labelledby="profile-tab-appearance"><AuthorProfileSettings :profile="profile"/></div>
 </template>
 <template v-else-if="path==='/me/bookmarks'||path==='/me/history'"><div v-if="path==='/me/history'&&rows.length" class="toolbar"><button class="danger" :disabled="busy" @click="clearHistory">清空足迹</button></div><div v-for="r in rows" :key="r.post_id||r.id" class="post-row"><div class="post-date">{{date(r.last_read_at||r.created_at)}}</div><div><h2><a :href="`/posts/${r.post_id||r.id}`">{{r.title}}</a></h2><p class="summary">{{r.summary}}</p><button v-if="path==='/me/bookmarks'" class="quiet" :disabled="busy" @click="removeBookmark(r)">取消收藏</button></div></div><div v-if="!rows.length" class="empty"><h2>{{path==='/me/history'?'阅读从一篇文章开始':'还没有收藏'}}</h2><p>这里只显示当前仍然公开的文章。</p><a href="/posts" class="button">发现文章</a></div></template>
 <template v-else-if="path==='/me/following'||path==='/me/followers'"><div class="tabs"><a class="button" href="/me/following" :aria-current="path==='/me/following'?'page':undefined">我的关注</a><a class="button" href="/me/followers" :aria-current="path==='/me/followers'?'page':undefined">我的粉丝</a></div><div class="panel user-list"><div v-for="r in rows" :key="r.id" class="user-row"><img v-if="r.avatar_url" class="avatar" :src="r.avatar_url" width="40" height="40" alt=""><span v-else class="avatar">{{(r.display_name||'?').slice(0,1)}}</span><div class="user-info"><a :href="`/users/${r.id}`"><strong>{{r.display_name}}</strong></a><p class="meta">{{r.bio}}</p></div><button :disabled="busy" @click="follow(r)">{{r.followed===false?'关注':'取消关注'}}</button></div><div v-if="!rows.length" class="empty">{{path==='/me/followers'?'还没有粉丝。持续分享，让读者慢慢找到你。':'还没有关注作者。可以从文章页认识一位作者。'}}</div></div></template>
 <template v-else-if="path==='/me/media'"><div class="panel table-scroll"><table class="data-table"><thead><tr><th>文件</th><th>状态</th><th>大小</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id||r.media_id"><td>{{r.original_name||r.name||r.id}}</td><td>{{mediaState(r)}}<span v-if="r.in_use" class="muted"> · 已被引用</span></td><td>{{(Number(r.byte_size||0)/1024).toFixed(1)}} KiB</td><td><div class="actions"><a v-if="r.state==='ready'" :href="`/media/${r.id||r.media_id}`" class="button quiet" target="_blank" rel="noopener">预览</a><button class="danger" :disabled="busy||!canDeleteMedia(r)" @click="deleteMedia(r)">删除未引用文件</button></div></td></tr></tbody></table><p v-if="!rows.length" class="muted">你上传的文章图片和头像会出现在这里。</p></div></template><template v-else-if="path==='/me/sessions'"><div class="panel"><div v-for="r in rows" :key="r.id" class="user-row"><div class="user-info"><strong>{{r.current?'当前会话':'其他登录会话'}}</strong><div class="meta">登录 {{date(r.created_at)}} · 最近使用 {{date(r.last_seen_at)}} · 到期 {{date(r.expires_at)}}</div></div><button class="danger" :disabled="busy" @click="revoke(r)">{{r.current?'退出当前':'撤销会话'}}</button></div></div></template>
 <template v-else-if="path==='/studio/settings'"><div class="settings-tabs" role="tablist" aria-label="站点设置分区" @keydown="settingsKey"><button v-for="tab in [{id:'site',label:'网站信息'},{id:'features',label:'功能与通知'},{id:'security',label:'登录安全'}]" :key="tab.id" type="button" role="tab" :tabindex="settingsSection===tab.id?0:-1" :aria-selected="settingsSection===tab.id" :aria-controls="'settings-'+tab.id" @click="changeSection(tab.id)">{{tab.label}}</button></div><form id="settings-site" v-show="settingsSection==='site'" role="tabpanel" aria-label="网站信息" class="panel" @submit.prevent="saveSite"><h2>网站信息</h2><div class="form-grid"><label>站点名称<input v-model="site.display_name" required></label><label>一句介绍<input v-model="site.tagline"></label><label>介绍姓名<input v-model="site.intro_name" maxlength="80" placeholder="首页里的自我介绍姓名"></label><label>身份与兴趣<input v-model="introRolesText" placeholder="用顿号或逗号分隔，最多12个"><small class="muted">例如 Golang工程师、摄影佬。来自你自己的真实介绍。</small></label><label>站点头像<img v-if="site.avatar_media_id" class="avatar" :src="'/media/'+site.avatar_media_id" width="40" height="40" alt=""><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" @change="siteAvatarUpload"></label><div v-if="site.avatar_media_id"><button type="button" class="quiet" @click="site.avatar_media_id=null">移除站点头像</button></div><label class="full">关于页面（Markdown）<textarea v-model="site.about_markdown" rows="6"></textarea></label><label class="full">搜索摘要<textarea v-model="site.seo_description" rows="2"></textarea></label><div class="full"><h3>社交链接</h3><div v-for="(link,i) in site.social_links" :key="i" class="user-row"><label class="user-info">显示名称<input v-model="link.label" required placeholder="例如 GitHub"></label><label class="user-info">链接地址<input v-model="link.url" type="url" required placeholder="https://"></label><button type="button" class="quiet danger" @click="site.social_links.splice(i,1)">移除</button></div><button type="button" @click="site.social_links.push({label:'',url:''})">添加链接</button></div></div><div class="form-actions"><button class="primary" :disabled="busy">保存网站信息</button><span v-if="siteDirty" class="muted" role="status">有未保存的修改</span></div></form><form id="settings-features" v-show="settingsSection==='features'" role="tabpanel" aria-label="功能与通知" class="panel" @submit.prevent="saveSettings"><h2>功能与通知</h2><p class="muted">当前仅保存邮件服务配置，自动通知尚未开放。</p><div class="form-grid"><label v-for="[key,label] in [['comments_enabled','允许评论'],['collections_enabled','允许收藏'],['follows_enabled','允许关注'],['analytics_enabled','开启访问分析'],['mail_enabled','保存邮件服务配置'],['rss_enabled','开启 RSS 订阅']]" :key="key" class="check"><input type="checkbox" v-model="settings[key]">{{label}}</label><fieldset class="full floating-settings"><legend>右侧浮动工具</legend><p class="muted">按页面选择可用工具。创作入口仅对站长与作者显示；全部取消时隐藏该场景的浮控。</p><div v-for="scene in [{key:'home',label:'首页'},{key:'article',label:'文章页'},{key:'other',label:'其他页面'}]" :key="scene.key" class="floating-scene"><strong>{{scene.label}}</strong><label v-for="control in [{key:'theme',label:'主题'},{key:'top',label:'回到顶部'},{key:'bottom',label:'到达底部'},{key:'like',label:'点赞'},{key:'account',label:'我的账号'},{key:'create',label:'创作入口'}].filter(c=>scene.key==='article'||!['like','bottom'].includes(c.key))" :key="control.key" class="check"><input type="checkbox" v-model="settings.floating_controls[scene.key]" :value="control.key">{{control.label}}</label></div></fieldset><label>SMTP 服务器<input v-model="settings.smtp_host" autocomplete="off"></label><label>端口<input v-model.number="settings.smtp_port" type="number" min="1" max="65535"></label><label>SMTP 用户名<input v-model="settings.smtp_username" autocomplete="off"></label><label>SMTP 密码<input v-model="settings.smtp_password" type="password" autocomplete="new-password" :placeholder="settings.smtp_password_configured?'已配置，留空保持':'尚未配置'"></label><label>发信地址<input v-model="settings.mail_from" type="email"></label></div><div class="form-actions"><button class="primary" :disabled="busy">保存功能设置</button><span v-if="settingsDirty" class="muted" role="status">有未保存的修改</span></div></form></template>
 <HomepageManager v-else-if="path==='/studio/home'&&session.user?.role==='owner'"/>
 <MomentManager v-else-if="path==='/studio/moments'" :owner="session.user?.role==='owner'"/>
 <TagManager v-else-if="path==='/studio/taxonomy'"/>
 <template v-else-if="path==='/studio/members'"><div class="panel"><div v-for="r in rows" :key="r.id" class="user-row"><div class="user-info"><strong>{{r.display_name}}</strong><div class="meta">@{{r.username}} · ID {{r.id}}</div></div><SelectField v-model="r.role" :disabled="busy" :label="'角色 · '+r.display_name" :options="[{value:'reader',label:'读者'},{value:'author',label:'作者'},{value:'owner',label:'站长'}]"/><label class="check"><input type="checkbox" v-model="r.disabled">停用</label><button :disabled="busy" @click="saveMember(r)">保存权限</button></div></div></template>
 <template v-else-if="path==='/studio/comments'"><label>本次治理原因<input v-model="moderationReason" maxlength="500" placeholder="向审计记录说明原因"></label><div class="panel" style="margin-top:24px"><div v-for="r in rows" :key="r.id" class="comment"><div class="meta">{{r.user?.display_name||r.display_name}} · {{date(r.created_at)}} · {{r.state}}</div><p class="comment-body">{{r.body}}</p><div class="toolbar"><a :href="`/posts/${r.post_id}`" class="button quiet">查看文章</a><span v-if="r.state==='deleted'" class="muted">已删除，无法恢复</span><button v-else-if="r.state==='visible'||r.state==='hidden'" :disabled="busy" @click="moderate(r,r.state==='visible'?'hidden':'visible')">{{r.state==='visible'?'隐藏评论':'恢复可见'}}</button></div></div><p v-if="!rows.length" class="muted">暂时没有需要查看的评论。</p></div></template>
 <template v-else-if="path==='/studio/analytics'"><form class="filter-bar" @submit.prevent="load()"><label>开始日期<input v-model="range.from" type="date" required></label><label>结束日期<input v-model="range.to" type="date" required></label><button>查看报表</button></form><div class="notice">UV 和有效阅读是观测估算；每日 UV 不相加为月 UV。迁移前口径单独保留。</div><div class="metric-grid"><div v-for="m in totals" :key="m.key" class="metric"><span>{{metricLabel(m.key)}}</span><strong>{{m.value.toLocaleString()}}</strong></div></div><p class="meta">统计截至 {{report.data_as_of||'尚无聚合数据'}} · 待处理 {{report.pending_count||0}} · 标识覆盖率 {{report.coverage==null?'暂无':(Number(report.coverage)*100).toFixed(1)+'%'}}</p><div class="panel table-scroll"><table class="data-table"><thead><tr><th>日期</th><th>范围</th><th>PV</th><th>日 UV</th><th>有效阅读</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td>{{r.day_key||r.day}}</td><td>{{r.resource_key||'site'}}</td><td>{{r.page_views||0}}</td><td>{{r.unique_visitors||0}}</td><td>{{r.post_reads||0}}</td></tr></tbody></table><p v-if="!rows.length" class="muted">这个日期范围还没有聚合数据。</p></div><section v-for="[key,label] in [['business','业务事实'],['legacy','迁移前统计']]" :key="key" class="panel"><h2>{{label}}</h2><div v-if="report[key]?.length" class="table-scroll"><table class="data-table"><thead><tr><th v-for="k in Object.keys(report[key][0])" :key="k">{{metricLabel(k)}}</th></tr></thead><tbody><tr v-for="(r,i) in report[key]" :key="i"><td v-for="(value,k) in r" :key="k">{{value}}</td></tr></tbody></table></div><p v-else class="muted">暂无记录。</p></section></template>
 <template v-else-if="path==='/studio/operations'"><section class="panel"><h2>存储用量</h2><dl class="operations-list"><dt>数据库</dt><dd>{{(Number(report.storage?.database_bytes||0)/1048576).toFixed(2)}} MiB</dd><dt>可用媒体</dt><dd>{{report.storage?.ready_media_count||0}} 个 · {{(Number(report.storage?.ready_media_bytes||0)/1048576).toFixed(2)}} MiB</dd><dt>媒体磁盘实际占用</dt><dd>{{report.storage?.media_file_count||0}} 个文件 · {{(Number(report.storage?.media_disk_bytes||0)/1048576).toFixed(2)}} MiB</dd></dl><h3 style="margin-top:28px">备份与恢复</h3><p>{{({not_observed:'尚无可验证的备份记录',artifact_created:'已生成备份文件，尚未验证恢复',restore_verified:'本地隔离恢复检查已通过'} as Row)[report.storage?.backup?.status]||'备份状态暂不可用'}}</p><dl v-if="report.storage?.backup?.latest" class="operations-list"><template v-for="(value,key) in report.storage.backup.latest" :key="key"><dt>{{({id:'备份编号',origin:'备份来源',name:'文件名',created_at:'创建时间',manifest_sha256:'媒体清单校验值',database_sha256:'数据库校验值',media_objects:'媒体对象数',media_bytes:'媒体字节数',restore_verified_at:'恢复验证时间'} as Row)[key]||key}}</dt><dd>{{key==='origin'?({local:'本机创建',imported:'外部导入'} as Row)[String(value)]||value:value??'—'}}</dd></template></dl><p class="muted">本地恢复通过只证明该快照可在隔离环境恢复；异机副本和定期备份仍需单独配置与验证。</p></section><section class="panel"><h2>事件聚合</h2><dl class="operations-list"><dt>待处理事件</dt><dd>{{report.jobs?.analytics?.pending_count||0}}</dd><dt>最早待处理</dt><dd>{{report.jobs?.analytics?.oldest_pending_at||'无积压'}}</dd><dt>当前延迟</dt><dd>{{Math.round(Number(report.jobs?.analytics?.lag_ms||0)/1000)}} 秒</dd></dl></section><section class="panel table-scroll"><h2>后台任务</h2><table class="data-table"><thead><tr><th>状态</th><th>数量</th><th>最早创建</th><th>最高尝试次数</th></tr></thead><tbody><tr v-for="r in report.jobs?.items||[]" :key="r.state"><td>{{({pending:'等待执行',processing:'处理中',done:'已完成',dead:'需要处理'} as Row)[r.state]||r.state}}</td><td>{{r.count}}</td><td>{{date(r.oldest_at)}}</td><td>{{r.max_attempts}}</td></tr></tbody></table></section><section class="panel"><h2>需要处理的任务</h2><p v-if="!report.jobs?.dead_tasks?.length" class="muted">目前没有进入失败队列的任务。</p><div v-for="r in report.jobs?.dead_tasks||[]" :key="r.id" class="user-row"><div class="user-info"><strong>{{r.topic}}</strong><div class="meta">{{date(r.created_at)}} · 已尝试 {{r.attempts}} 次</div><p>{{r.error}}</p></div></div></section></template>
 <InfiniteList v-if="endpoint()" :has-more="hasMore" :loading="loading" :disabled="busy" :error="error" @load="load(true)"/>
 </template></template><section id="settings-security" v-show="settingsSection==='security'" role="tabpanel" aria-label="登录安全" v-if="path==='/studio/settings'&&settingsSecuritySeen&&dataLoaded&&session.user?.role==='owner'"><div v-if="phone" class="phone-task-tabs phone-security-tabs" role="tablist" aria-label="登录安全任务" @keydown="taskTabsKey"><button v-for="tab in phoneSecurityTabs" :key="tab.id" type="button" role="tab" :tabindex="phoneSecuritySection===tab.id?0:-1" :aria-selected="phoneSecuritySection===tab.id" :aria-controls="'phone-security-'+tab.id" @click="phoneSecuritySection=tab.id">{{tab.label}}</button></div><div id="phone-security-access" v-show="!phone||phoneSecuritySection==='access'" :role="phone?'tabpanel':undefined" aria-label="访问控制"><LoginPolicySettings :settings="settings" @saved="Object.assign(settings,$event)"/></div><div id="phone-security-github" v-if="phoneSecuritySeen.has('github')" v-show="!phone||phoneSecuritySection==='github'" :role="phone?'tabpanel':undefined" aria-label="GitHub 登录"><GitHubSettings/></div><div id="phone-security-clients" v-if="phoneSecuritySeen.has('clients')" v-show="!phone||phoneSecuritySection==='clients'" :role="phone?'tabpanel':undefined" aria-label="应用接入"><IdentityClients/></div></section><section id="phone-profile-security" v-if="path==='/me'&&dataLoaded&&session.authenticated&&profileSectionsSeen.has('security')" v-show="phoneProfileSection==='security'" role="tabpanel" aria-labelledby="profile-tab-security"><AccountSecurity @updated="profile.version=$event"/><PasswordForm/></section></main><nav v-if="phone&&session.authenticated&&!editing" class="studio-phone-navigation" data-search-glass aria-label="工作台常用功能"><a :href="contentDestination" :aria-current="path===contentDestination?'page':undefined"><Icon :name="canCreate?'posts':'bookmark'" :size="21"/><span>{{canCreate?'内容':'收藏'}}</span></a><a v-if="canCreate" href="/studio/posts/new"><Icon name="pen" :size="21"/><span>新建</span></a><a href="/me" :aria-current="path==='/me'?'page':undefined"><Icon name="user" :size="21"/><span>我的</span></a><button type="button" aria-haspopup="dialog" :aria-expanded="drawerOpen" @click="openDrawer"><Icon name="menu" :size="21"/><span>全部</span></button></nav></div>
</template>
